#!/usr/bin/env bash
set -euo pipefail
WORKSPACE="/home/kavia/workspace/code-generation/native-notes-app-197439-197458/notes_native_app"
DEVUSER=devuser
LOGDIR="$WORKSPACE/logs"
TESTTMP="$WORKSPACE/tmp"
sudo -u "$DEVUSER" bash -lc "mkdir -p '$LOGDIR' '$TESTTMP' '$WORKSPACE/test' || true"
# ensure package.json has test script
sudo -u "$DEVUSER" bash -lc "cd '$WORKSPACE' && cp package.json package.json.test.bak 2>/dev/null || true && node -e '
const fs=require("fs"),p=JSON.parse(fs.readFileSync("package.json","utf8"));p.scripts=p.scripts||{};p.scripts.test=p.scripts.test||"jest --runInBand";fs.writeFileSync("package.json",JSON.stringify(p,null,2));console.log("test script ensured");'"
# write an isolated test that forces DB into tmp folder
sudo -u "$DEVUSER" tee "$WORKSPACE/test/db.test.js" >/dev/null <<'T'
const fs=require('fs'), path=require('path');
const tempdir=path.join(__dirname,'..','tmp');
const dbPath=path.join(tempdir,'notes.test.db');
afterEach(()=>{ try{ if(fs.existsSync(dbPath)) fs.unlinkSync(dbPath); }catch(e){} });
test('creates sqlite file via db module', done=>{
  // require module but override path used by src/db by copying a tiny shim
  const shim=path.join(__dirname,'..','src','db.js');
  const content=require('fs').readFileSync(shim,'utf8').replace(/notes\.db/g,'notes.test.db');
  require('fs').writeFileSync(path.join(tempdir,'db_shim.js'),content);
  const db=require(path.join(tempdir,'db_shim.js'));
  db.serialize(()=>{
    db.get("SELECT name FROM sqlite_master WHERE type='table' AND name='notes'", (err,row)=>{
      expect(err).toBeNull();
      expect(row).not.toBeUndefined();
      db.close(()=>done());
    });
  });
});
T
# run tests using local jest
if [ ! -x "$WORKSPACE/node_modules/.bin/jest" ]; then echo "ERROR: local jest not found" >&2; exit 2; fi
sudo -u "$DEVUSER" bash -lc "cd '$WORKSPACE' && ./node_modules/.bin/jest --runInBand 2>&1 | tee -a '$LOGDIR/jest.log'" || { echo "ERROR: tests failed; see $LOGDIR/jest.log" >&2; exit 3; }
exit 0

